    @PageSize INT=50, @PageNumber INT=1
AS BEGIN
    SET NOCOUNT ON;
    SELECT o.OrderId,o.OrderDate,o.TotalAmount,o.StatusCode
    FROM dbo.Orders AS o
    WHERE o.CustomerId=@CustomerId
    AND (@StatusCode IS NULL OR o.StatusCode=@StatusCode);
END;

BEGIN TRANSACTION;
BEGIN TRY
    UPDATE dbo.Accounts SET Balance=Balance-@Amount WHERE AccountId=@FromId;
    UPDATE dbo.Accounts SET Balance=Balance+@Amount WHERE AccountId=@ToId;
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    ROLLBACK TRANSACTION;
    THROW;
END CATCH;

SET STATISTICS IO ON; SET STATISTICS TIME ON;
SELECT TOP 100 o.OrderId,c.Name,SUM(ol.Quantity) AS TotalQty
FROM dbo.Orders o
JOIN dbo.Customers c ON c.CustomerId=o.CustomerId
JOIN dbo.OrderLines ol ON ol.OrderId=o.OrderId
WHERE o.CreatedAt >= DATEADD(MONTH,-3,SYSUTCDATETIME())
GROUP BY o.OrderId,c.Name ORDER BY TotalQty DESC;
SET STATISTICS IO OFF; SET STATISTICS TIME OFF;

WITH RecentOrders AS (
    SELECT OrderId,CustomerId,TotalAmount,CreatedAt FROM dbo.Orders
    WHERE CreatedAt >= DATEADD(DAY,-30,SYSUTCDATETIME())
), CustomerSpend AS (
    SELECT CustomerId,SUM(TotalAmount) AS Spend30Day
    FROM RecentOrders GROUP BY CustomerId
)
SELECT c.Name,cs.Spend30Day FROM dbo.Customers AS c
JOIN CustomerSpend AS cs ON cs.CustomerId=c.CustomerId
ORDER BY cs.Spend30Day DESC;

